export function isCappadociaMap(r){const b=r?.bounds;return r?.zone===36&&r?.hemisphere==='N'&&Array.isArray(b)&&b.length===2&&Math.abs(b[0][0]-38.511431169702625)<.00003&&Math.abs(b[0][1]-34.728930734172124)<.00003&&Math.abs(b[1][0]-38.77929917607526)<.00003&&Math.abs(b[1][1]-35.06375032295786)<.00003;}
